(function(global){
var io=function(){
  var handlers={};
  global._io_handlers=handlers;
  return {
    on:function(ev,fn){if(!handlers[ev])handlers[ev]=[];handlers[ev].push(fn);return this;},
    emit:function(){}
  };
};
global.io=io;
global._pollForResult=function(uuid){
  var tries=0;
  var interval=setInterval(function(){
    tries++;
    fetch('/flights/delays/predict/classify_realtime/response/'+uuid)
      .then(function(r){return r.json();})
      .then(function(data){
        if(data.status==='OK' && data.prediction){
          clearInterval(interval);
          var pred=data.prediction;
          pred.UUID=uuid;
          var h=global._io_handlers['prediction_response'];
          if(h)h.forEach(function(f){f(pred);});
        }
      }).catch(function(){});
    if(tries>30)clearInterval(interval);
  },1000);
};
})(window);